        "_layer_norm_fwd": "def _layer_norm_fwd(x,\n                    weight,\n                    bias,\n                    eps,\n                    z=None,\n                    out=None,\n                    group_size=None,\n                    norm_before_gate=True,\n                    is_rms_norm=False):\n    \"\"\"\n    Forward pass for layer normalization with optional gating.\n    \n    Args:\n        x: Input tensor of shape [*, hidden_size]\n        weight: Weight tensor of shape [hidden_size]\n        bias: Bias tensor of shape [hidden_size] or None\n        eps: Epsilon for numerical stability\n        z: Gate tensor of shape [*, hidden_size] or None\n        out: Output tensor or None\n        group_size: Group size for group normalization or None\n        norm_before_gate: If True, normalize before applying gate\n        is_rms_norm: If True, use RMSNorm instead of LayerNorm\n    \"\"\"\n    # Flatten input if needed\n    original_shape = x.shape\n    x = x.reshape(-1, x.shape[-1])\n    M, N = x.shape\n    \n    if z is not None:\n        z = z.reshape(-1, z.shape[-1])\n        assert z.shape == (M, N), f\"Gate shape {z.shape} doesn't match input shape {(M, N)}\"\n    \n    # Allocate output\n    if out is None:\n        out = torch.empty_like(x)\n    \n    # Choose block size\n    def get_block_size(N):\n        # Heuristic for block size\n        if N <= 1024:\n            return 128\n        elif N <= 4096:\n            return 256\n        else:\n            return 512\n    \n    BLOCK_N = get_block_size(N)\n    \n    # Launch kernel\n    grid = (M,)\n    _layer_norm_fwd_1pass_kernel[grid](\n        x, out, weight, bias, z,\n        None, None,  # Mean and Rstd not stored for now\n        x.stride(0), out.stride(0),\n        z.stride(0) if z is not None else 0,\n        M, N, eps, BLOCK_N,\n        bias is not None, z is not None,\n        norm_before_gate, is_rms_norm\n    )\n    \n    # Reshape output\n    out = out.reshape(original_shape)\n    return out",
        "_layer_norm_fwd_1pass_kernel": "@triton.heuristics({\"HAS_BIAS\": lambda args: args[\"B\"] is not None})\n@triton.heuristics({\"HAS_Z\": lambda args: args[\"Z\"] is not None})\n@triton.jit\ndef _layer_norm_fwd_1pass_kernel(\n    X,  # pointer to the input\n    Y,  # pointer to the output\n    W,  # pointer to the weights\n    B,  # pointer to the biases\n    Z,  # pointer to the other branch (gate)\n    Mean,  # pointer to the mean\n    Rstd,  # pointer to the 1/std\n    stride_x_row: tl.int64,\n    stride_y_row: tl.int64,\n    stride_z_row: tl.int64,\n    M: tl.int64,  # number of rows in X\n    N: tl.int64,  # number of columns in X\n    eps,  # epsilon to avoid division by zero\n    BLOCK_N: tl.constexpr,\n    HAS_BIAS: tl.constexpr,\n    HAS_Z: tl.constexpr,\n    NORM_BEFORE_GATE: tl.constexpr,\n    IS_RMS_NORM: tl.constexpr,\n):\n    # Map the program id to the row of X and Y it should compute.\n    row = tl.program_id(0)\n    X += row * stride_x_row\n    Y += row * stride_y_row\n    if HAS_Z:\n        Z += row * stride_z_row\n    \n    # Load a block of columns\n    cols = tl.arange(0, BLOCK_N)\n    mask = cols < N\n    \n    # Load input\n    x = tl.load(X + cols, mask=mask, other=0.0).to(tl.float32)\n    \n    # Apply gating if Z is provided\n    if HAS_Z:\n        z = tl.load(Z + cols, mask=mask, other=0.0).to(tl.float32)\n        # Apply SiLU activation to gate\n        # SiLU(x) = x * sigmoid(x)\n        sigmoid_z = 1.0 / (1.0 + tl.exp(-z))\n        silu_z = z * sigmoid_z\n        \n        if NORM_BEFORE_GATE:\n            # First normalize x, then apply gate\n            # For RMSNorm: compute variance\n            xbar = tl.where(mask, x, 0.0)\n            var = tl.sum(xbar * xbar, axis=0) / N\n            rstd = 1.0 / tl.sqrt(var + eps)\n            x_norm = x * rstd\n            # Apply gate after normalization\n            y = x_norm * silu_z\n        else:\n            # Apply gate first, then normalize (RMSNorm(x * SiLU(gate)))\n            y = x * silu_z\n            # For RMSNorm: compute variance\n            ybar = tl.where(mask, y, 0.0)\n            var = tl.sum(ybar * ybar, axis=0) / N\n            rstd = 1.0 / tl.sqrt(var + eps)\n            y = y * rstd\n    else:\n        # No gating, just normalize\n        y = x\n        # For RMSNorm: compute variance\n        ybar = tl.where(mask, y, 0.0)\n        var = tl.sum(ybar * ybar, axis=0) / N\n        rstd = 1.0 / tl.sqrt(var + eps)\n        y = y * rstd\n    \n    # Store rstd for backward pass if needed\n    if Rstd is not None:\n        tl.store(Rstd + row, rstd)\n    \n    # Apply weight and bias\n    w = tl.load(W + cols, mask=mask).to(tl.float32)\n    y = y * w\n    \n    if HAS_BIAS:\n        b = tl.load(B + cols, mask=mask).to(tl.float32)\n        y = y + b\n    \n    # Write output\n    tl.store(Y + cols, y, mask=mask)"
    }
}
EOF"}

